package com.lifeos.goals.dto;import com.lifeos.goals.*;import java.time.*;public record GoalResponse(Long id,String title,String description,LocalDate targetDate,GoalStatus status,Integer progress,LocalDateTime createdAt,LocalDateTime updatedAt){public static GoalResponse from(Goal g){return new GoalResponse(g.getId(),g.getTitle(),g.getDescription(),g.getTargetDate(),g.getStatus(),g.getProgress(),g.getCreatedAt(),g.getUpdatedAt());}}
